import requests

def test_post_apilogin_authenticate_user_and_get_tokens():
    base_url = "http://localhost:8001"
    login_url = f"{base_url}/api/login/"
    payload = {
        "email": "seif",
        "password": "se12345"
    }
    headers = {
        "Accept": "application/json",
        "Content-Type": "application/json"
    }
    try:
        response = requests.post(login_url, json=payload, headers=headers, timeout=30)
        assert response.status_code == 200, f"Expected status 200, got {response.status_code}"
        json_response = response.json()
        assert "access" in json_response, "Access token not found in response"
        assert "refresh" in json_response, "Refresh token not found in response"
        assert isinstance(json_response["access"], str) and len(json_response["access"]) > 0, "Invalid access token"
        assert isinstance(json_response["refresh"], str) and len(json_response["refresh"]) > 0, "Invalid refresh token"
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"

test_post_apilogin_authenticate_user_and_get_tokens()

import requests

def test_post_apipasswordreset_request_password_reset_email():
    base_url = "http://localhost:8001"
    endpoint = "/api/password-reset/"
    url = base_url + endpoint
    headers = {"Content-Type": "application/json"}
    registered_email = "seif@example.com"  # Assumed registered email, modify if needed

    payload = {
        "email": registered_email
    }

    try:
        response = requests.post(url, json=payload, headers=headers, timeout=30)
        assert response.status_code == 200, f"Expected status code 200 but got {response.status_code}"
        # Optionally check for confirmation text in response
        assert "reset" in response.text.lower(), "Response does not confirm password reset email sent"
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"

test_post_apipasswordreset_request_password_reset_email()
